15	        wasip1::RIGHTS_FD_WRITE,
16	        0,
17	        0,
18	    )
19	    .expect("creating a file for writing");
20	
21	    // Write to the file
22	    let content = b"this content will be truncated!";
23	    let nwritten = wasip1::fd_write(
24	        file_fd,
25	        &[wasip1::Ciovec {
26	            buf: content.as_ptr() as *const _,
27	            buf_len: content.len(),
28	        }],
29	    )
30	    .expect("writing file content");
