32	
33	    wasip1::fd_close(file_fd).expect("closing the file");
34	
35	    // Open the file for truncation
36	    let file_fd = wasip1::path_open(
37	        dir_fd,
38	        0,
39	        FILENAME,
40	        wasip1::OFLAGS_CREAT | wasip1::OFLAGS_TRUNC,
41	        wasip1::RIGHTS_FD_WRITE | wasip1::RIGHTS_FD_READ,
42	        0,
43	        0,
44	    )
45	    .expect("creating a truncated file for reading");
46	
47	    // Read the file's contents
48	    let buffer = &mut [0u8; 100];
49	    let nread = wasip1::fd_read(
50	        file_fd,
51	        &[wasip1::Iovec {
52	            buf: buffer.as_mut_ptr(),
53	            buf_len: buffer.len(),
54	        }],
55	    )
56	    .expect("reading file content");
57	
58	    // The file should be empty due to truncation
59	    assert_eq!(nread, 0, "expected an empty file after truncation");
60	
61	    wasip1::fd_close(file_fd).expect("closing the file");
62	}
